package org.bukkit; public class Bukkit { public static Server server; public static org.bukkit.entity.Player player; public static org.bukkit.plugin.PluginManager getPluginManager(){return server.getPluginManager();} public static org.bukkit.entity.Player getPlayerExact(String n){return player!=null&&player.getName().equals(n)?player:null;} public static org.bukkit.command.CommandSender getConsoleSender(){return null;} public static boolean dispatchCommand(org.bukkit.command.CommandSender s,String c){return true;} }
